I have everything verified: `Client(fastmcp_server_instance)` auto-uses the in-memory transport, `read_resource(uri)` is async and returns a list of `TextResourceContents`/`BlobResourceContents`.

```python
import asyncio

from fastmcp import FastMCP
from fastmcp.client import Client

server = FastMCP("ConfigServer")


@server.resource("data://config")
def get_config() -> dict:
    return {"debug": False, "version": "1.0.0"}


async def main() -> None:
    client = Client(server)

    async with client:
        contents = await client.read_resource("data://config")
        for item in contents:
            if hasattr(item, "text"):
                print(item.text)
            else:
                print(item.blob)


if __name__ == "__main__":
    asyncio.run(main())
